function About() {
  return (
    <section className="about">
      <h1>About Paws Shelter</h1>
      <p>
        We are a small (and imaginary) shelter full of animals looking for a
        family. Adopting is easy:
      </p>
      <ul>
        <li>1️⃣ Browse the pets and filter by type</li>
        <li>2️⃣ Open a pet to read its story</li>
        <li>3️⃣ Click "Adopt" and fill the short form</li>
        <li>4️⃣ Go home with a new best friend 🏡</li>
      </ul>
    </section>
  );
}

export default About;
